<script setup lang="ts">import { ref } from "vue"; import { post } from "../api"; const email=ref(""), password=ref(""), message=ref(""); async function submit(){const result=await post<{user:{name:string}}>("/auth/login",{email:email.value,password:password.value});message.value=`欢迎，${result.user.name}`;}</script><template><h1>登录 FlowTask</h1><div class="panel"><div class="row"><input v-model="email" aria-label="邮箱"><input v-model="password" type="password" aria-label="密码"><button @click="submit">登录</button></div><p>{{message}}</p></div></template>
